__NUXT_JSONP__("/en/tf_material/thanks", (function(a,b){return {data:[{details:{slug:"en",pageTitle:"Thanks for Downloading our Brochure | Mentor Language Institute",pageDescription:b,title:"Thanks for Downloading our Brochure",subtitle:[b,"Please download the brochure using the links below."],brochures:[{title:"Tuition Chart Westwood",image:"\u002Fimages\u002Ftf_material\u002FFee Chart WW.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2025 MLI - WW Tuition.pdf"},{title:"Tuition Chart Hollywood",image:"\u002Fimages\u002Ftf_material\u002FFee Chart HW.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2025 MLI - HW Tuition.pdf"},{title:"Program Schedule at Westwood Campus",image:"\u002Fimages\u002Ftf_material\u002FWestwood Schedule.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2025_MLI_WW_Class_Schedule.pdf"},{title:"Program Schedule at Hollywood Campus",image:"\u002Fimages\u002Ftf_material\u002FHollywood Schedule.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2025_MLI-HW_Class_Schedulepdf.pdf"},{title:"MLI Brochure & Program Schedule",image:"\u002Fimages\u002Fmaterial\u002Fmli-brochure-program-schedule-en.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2025 MLI School Brochure[EN]_OCT17.pdf"},{title:"Housing Brochure",image:"\u002Fimages\u002Fmaterial\u002F2022-housing-brochure.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F_Digital_ 2025 USSS Brochure- Only Housing updated 10.20.2024.pdf"}],other_info:["\u003Cspan class='hutoaka'\u003EAn admission staff will email you regarding your inquiry.\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EIf you have any questions regarding student visas, housing availability or anything else, please feel free to contact us anytime.","The process for studying abroad in the United States is very complicated, we can guide you the procedures over the phone.","If you didn't check \"Do not contact me by phone\", we will call you in a day or two.","\u003Cb\u003E【 WESTWOOD CAMPUS 】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E10880 Wilshire Blvd., Suite 122\u003Cbr \u002F\u003ELos Angeles, CA 90024\u003Cbr \u002F\u003ETEL: ＋1（310）887-0777\u003Cbr \u002F\u003EE-mail: info@mliesl.edu\u003Cbr \u002F\u003EOffice hours: Monday through Thursday 8:30 – 20:30, Friday 8:30 – 18:00","\u003Cb\u003E【 HOLLYWOOD CAMPUS 】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E7080 Hollywood Blvd., Suite 314\u003Cbr \u002F\u003ELos Angeles, CA 90028\u003Cbr \u002F\u003ETEL: ＋1（323）870-7102\u003Cbr \u002F\u003EE-mail: hollywood@mliesl.edu\u003Cbr \u002F\u003EOffice hours: Monday through Friday 8:30 – 17:00"],dir:"\u002Ftf_material",path:"\u002Ftf_material\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:31.240Z",updatedAt:"2025-05-26T12:06:27.939Z"}}],fetch:{},mutations:void 0}}("\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Download","Thank you for your request to download our school brochure and information package.")));